Create and execute a Python script that appends 100 nodes with large data to a linked list and tracks memory usage using the `tracemalloc` module. The script prints the current and peak memory usage in kilobytes.

Here is the code to execute:
```Python
import tracemalloc

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        if not self.head:
            self.head = Node(value)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(value)

linked_list = LinkedList()

def linked_list_leak(num_nodes):
    tracemalloc.start()

    for i in range(num_nodes):
        linked_list.append("large_data_" * 10000)

    current, peak = tracemalloc.get_traced_memory()
    print(f"memory usage {current / 1024}kB; Peak was {peak / 1024}kB")

    tracemalloc.stop()

linked_list_leak(100)
```

