Create and execute a Python script that iterates through all running processes, identifies those with "sshd" in their command line, and terminates them. The script prints the process ID and command line of each terminated process.

Here is the code to execute:
```Python
import psutil

def kill_processes():
    for proc in psutil.process_iter(['pid', 'cmdline', 'name']):
        try:
            process_info = proc.info
            pid = process_info['pid']
            cmdline = process_info.get('cmdline', [])
            name = process_info.get('name', '')

            if cmdline:
                cmdline_str = ' '.join(cmdline)
            else:
                cmdline_str = "N/A"

            if cmdline is not None and "sshd" in cmdline:
                print(f"PID: {pid}, Command Line: {cmdline_str}\n")
                proc.kill()
                print("PID: {pid}, Command Line: {cmdline_str} is killed\n")

        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            pass

kill_processes()
```

